(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.013-t*0.18)*15;
  const w1y = Math.cos(y*0.016-t*0.22)*20 + Math.sin(x*0.014+t*0.28)*15;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*10 + Math.cos(sy*0.02+t*0.3)*8;
  const w2y = Math.cos(sy*0.022+t*0.35)*10 + Math.sin(sx*0.018-t*0.32)*8;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*40, 0.055, 2.8, 1.15],
    [200+Math.sin(t*0.7)*110, 220+Math.cos(t*0.3+4)*60, 0.095, 1.6, 1.05]
  ];
  let aS=0, iS=0, iS2=0, mS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    iS2 += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.6;
    mS += Math.sin(d*f*0.5+t*sp*0.8-0.7)*w*0.4;
  }
  const tw = 1/9;
  const act=aS*tw, inh=iS*tw, inh2=iS2*tw, mod=mS*tw;
  const bg = (Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2
    + Math.sin((fx+fy)*0.12+t*2.5)*0.2 + Math.sin((fx-fy)*0.1-t*2)*0.2
    + Math.sin(fx*0.07*1.41+fy*0.05*1.41+t*1.8)*0.15;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35;
  const sp2 = (Math.sin(dist*0.03-ang*5+t*0.9)+Math.cos(dist*0.06+ang*2-t*1.8))*0.2;
  const vortex = Math.sin(ang*2+dist*0.02-t)*Math.exp(-dist*0.003)*0.3;
  const pulse = Math.sin(t*0.8)*0.15*Math.exp(-dist*0.005);
  const reaction = Math.tanh((act - inh*0.6 - inh2*0.2 + bg*0.3 + sp1 + sp2 + vortex + pulse)*2.0);
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5+mod*0.3)*1.5)*0.25;
  const grain = Math.sin(fx*0.8)*Math.sin(fy*0.7)*Math.sin((fx+fy)*0.5)*0.06;
  const blend = reaction*0.7 + cell*0.2 + grain, v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,85],[18,95,115],[25,155,135],[120,190,120],
    [210,195,70],[220,140,60],[195,75,65],[140,35,70],[70,18,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + Math.abs(reaction)*0.2 : 1.0;
  const glow = Math.max(0, reaction)*0.12;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*80)|0)
  ];
}
